def resolve(path, cwd, links):
    # Normalize the starting path
    if path.startswith('/'):
        current = '/'
        components = path.split('/')
    else:
        current = cwd
        components = path.split('/')

    # Track symlink resolution count
    link_count = 0
    max_links = 8

    # Process components left to right
    i = 0
    while i < len(components):
        component = components[i]
        i += 1

        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
                # Move to parent directory
                current = '/'.join(current.split('/')[:-1])
                if current == '':
                    current = '/'
            continue

        # Append component to current path
        if current == '/':
            current = '/' + component
        else:
            current = current + '/' + component

        # Check if this path is a symlink
        if current in links:
            link_count += 1
            if link_count > max_links:
                return None

            # Get the symlink target
            target = links[current]

            # If target starts with '/', it's absolute; otherwise relative to the directory containing the link
            if target.startswith('/'):
                current = '/'
                new_components = target.split('/')
            else:
                # Target is relative to the directory containing the link
                # current already points to the link, so we get its directory
                if current == '/':
                    dir_of_link = '/'
                else:
                    dir_of_link = '/'.join(current.split('/')[:-1])
                    if dir_of_link == '':
                        dir_of_link = '/'

                current = dir_of_link
                new_components = target.split('/')

            # Insert remaining components and new target components
            remaining_components = components[i:]
            components = new_components + remaining_components
            i = 0

    # Return result without trailing slash, except for '/'
    if current == '/':
        return '/'
    else:
        return current

